104→		Use:   "create",
105→		Short: "Create a new project",
106→		RunE: func(cmd *cobra.Command, args []string) error {
107→			if name == "" {
108→				return fmt.Errorf("--name is required")
109→			}
110→			if identifier == "" {
111→				return fmt.Errorf("--identifier is required")
112→			}
113→
114→			client, err := f.Client()
115→			if err != nil {
116→				return err
117→			}
118→			ws, err := f.RequireWorkspace()
119→			if err != nil {
120→				return err
121→			}
122→
123→			path, err := api.NewPath("workspaces/{workspace_slug}/projects/").
124→				Workspace(ws).Build()
125→			if err != nil {
126→				return err
127→			}
128→
129→			body := map[string]interface{}{
130→				"name":       name,
131→				"identifier": identifier,
132→			}
