  1→package api
  2→
  3→import (
  4→	"bytes"
  5→	"context"
  6→	"encoding/json"
  7→	"fmt"
  8→	"io"
  9→	"net/http"
 10→	"os"
 11→	"strings"
 12→	"time"
 13→
 14→	"golang.org/x/time/rate"
 15→)
 16→
 17→// Client is the HTTP client for Plane API.
 18→type Client struct {
 19→	httpClient *http.Client
 20→	baseURL    string
 21→	apiKey     string
 22→	limiter    *rate.Limiter
 23→	debug      bool
 24→}
 25→
 26→// ClientOption configures the Client.
 27→type ClientOption func(*Client)
 28→
 29→// WithDebug enables HTTP request/response logging.
 30→func WithDebug(debug bool) ClientOption {
 31→	return func(c *Client) {
 32→		c.debug = debug
 33→	}
 34→}
 35→
 36→// NewClient creates a new API client.
 37→func NewClient(baseURL, apiKey string, opts ...ClientOption) *Client {
 38→	// Normalize base URL
 39→	baseURL = strings.TrimRight(baseURL, "/")
 40→
 41→	c := &Client{
 42→		httpClient: &http.Client{
 43→			Timeout: 30 * time.Second,
 44→		},
 45→		baseURL: baseURL,
 46→		apiKey:  apiKey,
 47→		// 55 req/min with burst of 10 (safety margin from 60 req/min limit)
 48→		limiter: rate.NewLimiter(rate.Every(time.Minute/55), 10),
 49→	}
 50→
 51→	for _, opt := range opts {
 52→		opt(c)
 53→	}
 54→
 55→	return c
 56→}
 57→
 58→// do executes an HTTP request with rate limiting, auth, and error handling.
 59→func (c *Client) do(ctx context.Context, method, path string, body interface{}) (json.RawMessage, error) {
 60→	// Rate limiting
 61→	if err := c.limiter.Wait(ctx); err != nil {
 62→		return nil, fmt.Errorf("rate limit: %w", err)
 63→	}
 64→
 65→	// Build full URL
 66→	fullURL := c.baseURL + "/api/v1/" + strings.TrimLeft(path, "/")
 67→
 68→	// Prepare body
 69→	var bodyReader io.Reader
 70→	if body != nil {
 71→		data, err := json.Marshal(body)
 72→		if err != nil {
 73→			return nil, fmt.Errorf("marshaling request body: %w", err)
 74→		}
 75→		bodyReader = bytes.NewReader(data)
 76→	}
 77→
 78→	req, err := http.NewRequestWithContext(ctx, method, fullURL, bodyReader)
 79→	if err != nil {
 80→		return nil, fmt.Errorf("creating request: %w", err)
 81→	}
 82→
 83→	// Headers
 84→	req.Header.Set("X-API-Key", c.apiKey)
 85→	req.Header.Set("Content-Type", "application/json")
 86→	req.Header.Set("Accept", "application/json")
 87→
 88→	if c.debug {
 89→		fmt.Fprintf(os.Stderr, "[DEBUG] %s %s\n", method, fullURL)
 90→		if body != nil {
 91→			data, _ := json.MarshalIndent(body, "", "  ")
 92→			fmt.Fprintf(os.Stderr, "[DEBUG] Body: %s\n", string(data))
 93→		}
 94→	}
 95→
 96→	resp, err := c.httpClient.Do(req)
 97→	if err != nil {
 98→		return nil, fmt.Errorf("executing request: %w", err)
 99→	}
100→	defer resp.Body.Close()
101→
102→	respBody, err := io.ReadAll(resp.Body)
103→	if err != nil {
104→		return nil, fmt.Errorf("reading response: %w", err)
105→	}
106→
107→	if c.debug {
108→		fmt.Fprintf(os.Stderr, "[DEBUG] Response: %d %s\n", resp.StatusCode, resp.Status)
109→		if len(respBody) > 0 && len(respBody) < 2000 {
110→			fmt.Fprintf(os.Stderr, "[DEBUG] Body: %s\n", string(respBody))
111→		}
112→	}
113→
114→	// Handle errors
115→	if resp.StatusCode >= 400 {
116→		apiErr := parseAPIError(resp, respBody)
117→		return nil, apiErr
118→	}
119→
120→	// Handle 204 No Content
121→	if resp.StatusCode == http.StatusNoContent || len(respBody) == 0 {
122→		return json.RawMessage("null"), nil
123→	}
124→
125→	return json.RawMessage(respBody), nil
126→}
127→
128→// Get performs a GET request.
129→func (c *Client) Get(path string) (json.RawMessage, error) {
130→	return c.do(context.Background(), http.MethodGet, path, nil)
131→}
132→
133→// Post performs a POST request.
134→func (c *Client) Post(path string, body interface{}) (json.RawMessage, error) {
135→	return c.do(context.Background(), http.MethodPost, path, body)
136→}
137→
138→// Patch performs a PATCH request.
139→func (c *Client) Patch(path string, body interface{}) (json.RawMessage, error) {
140→	return c.do(context.Background(), http.MethodPatch, path, body)
141→}
142→
143→// Put performs a PUT request.
144→func (c *Client) Put(path string, body interface{}) (json.RawMessage, error) {
145→	return c.do(context.Background(), http.MethodPut, path, body)
146→}
147→
148→// Delete performs a DELETE request.
149→func (c *Client) Delete(path string) (json.RawMessage, error) {
150→	return c.do(context.Background(), http.MethodDelete, path, nil)
151→}
152→
153→// DeleteWithBody performs a DELETE request with a body.
154→func (c *Client) DeleteWithBody(path string, body interface{}) (json.RawMessage, error) {
155→	return c.do(context.Background(), http.MethodDelete, path, body)
156→}
