 1→package output
 2→
 3→import (
 4→	"encoding/json"
 5→)
 6→
 7→// Formatter defines the interface for output formatting.
 8→type Formatter interface {
 9→	Format(data interface{}) error
10→}
11→
12→// Format outputs data using the specified format.
13→func Format(format string, data interface{}, columns []Column) error {
14→	switch format {
15→	case "table":
16→		return NewTableFormatter(columns).Format(data)
17→	default:
18→		return NewJSONFormatter().Format(data)
19→	}
20→}
21→
22→// FormatRaw outputs raw JSON data.
23→func FormatRaw(format string, data json.RawMessage, columns []Column) error {
24→	switch format {
25→	case "table":
26→		return NewTableFormatter(columns).Format(data)
27→	default:
28→		return NewJSONRawFormatter().Format(data)
29→	}
30→}
31→
32→// Column defines a table column.
33→type Column struct {
34→	Header string
35→	Field  string
36→	Width  int
37→}
38→

 1→package output
 2→
 3→import (
 4→	"fmt"
 5→	"os"
 6→)
 7→
 8→// Quiet controls whether non-error output is suppressed.
 9→var Quiet bool
10→
11→// Print writes to stdout unless quiet mode is active.
12→func Print(format string, args ...interface{}) {
13→	if !Quiet {
14→		fmt.Fprintf(os.Stdout, format, args...)
15→	}
16→}
17→
18→// Println writes a line to stdout unless quiet mode is active.
19→func Println(args ...interface{}) {
20→	if !Quiet {
21→		fmt.Fprintln(os.Stdout, args...)
22→	}
23→}
24→
25→// Error writes to stderr (always shown, even in quiet mode).
26→func Error(format string, args ...interface{}) {
27→	fmt.Fprintf(os.Stderr, format, args...)
28→}
29→
30→// Errorln writes a line to stderr.
31→func Errorln(args ...interface{}) {
32→	fmt.Fprintln(os.Stderr, args...)
33→}
34→
35→// PrintID prints just an ID (useful for quiet mode after create/update).
36→func PrintID(id string) {
37→	fmt.Println(id)
38→}
