 12→
 13→// NewCmd creates the issue command.
 14→func NewCmd(f *cmdutil.Factory) *cobra.Command {
 15→	cmd := &cobra.Command{
 16→		Use:     "issue",
 17→		Aliases: []string{"i"},
 18→		Short:   "Manage work items (issues)",
 19→	}
 20→
 21→	cmd.AddCommand(newListCmd(f))
 22→	cmd.AddCommand(newGetCmd(f))
 23→	cmd.AddCommand(newGetBySeqCmd(f))
 24→	cmd.AddCommand(newSearchCmd(f))
 25→	cmd.AddCommand(newCreateCmd(f))
 26→	cmd.AddCommand(newUpdateCmd(f))
 27→	cmd.AddCommand(newDeleteCmd(f))
 28→
 29→	return cmd
 30→}
 31→
 32→var issueColumns = []output.Column{
 33→	{Header: "ID", Field: "id"},
 34→	{Header: "SEQ", Field: "sequence_id"},
 35→	{Header: "NAME", Field: "name"},
 36→	{Header: "STATE", Field: "state"},
 37→	{Header: "PRIORITY", Field: "priority"},
 38→	{Header: "ASSIGNEES", Field: "assignees"},
 39→}
 40→
 41→func workItemPath() string {
 42→	return "workspaces/{workspace_slug}/projects/{project_id}/work-items/"
 43→}
 44→
 45→func newListCmd(f *cmdutil.Factory) *cobra.Command {
 46→	var state, priority, assignee string
 47→	var perPage int
 48→	var cursor string
 49→
 50→	cmd := &cobra.Command{
 51→		Use:   "list",
 52→		Short: "List issues in a project",
 53→		RunE: func(cmd *cobra.Command, args []string) error {
 54→			client, err := f.Client()
 55→			if err != nil {
 56→				return err
 57→			}
 58→			ws, proj, err := f.RequireWorkspaceAndProject()
 59→			if err != nil {
 60→				return err
 61→			}
 62→
 63→			p := api.NewPath(workItemPath()).Workspace(ws).Project(proj)
 64→			p.QueryInt("per_page", perPage)
